use vstd::prelude::*;

verus! {

    // hermeline constructs a length‐2 vector [off, s] where
    //   s == 0.0 if and only if scl == 0.0,
    //   otherwise s == scl.
    fn hermeline(off: f64, scl: f64) -> (coeffs: Vec<f64>)
        ensures
            coeffs.len() == 2,
            // first element equals off
            coeffs.index(0) == off,
            // second element is exactly 0.0 when scl is zero
            (scl == 0.0 ==> coeffs.index(1) == 0.0),
            // otherwise second element equals scl
            (scl != 0.0 ==> coeffs.index(1) == scl),
    {
        // start with an empty vector
        let mut coeffs: Vec<f64> = Vec::new();
        // push the offset
        coeffs.push(off);
        // choose second entry by case on scl
        let second = if scl == 0.0 { 0.0 } else { scl };
        coeffs.push(second);
        coeffs
    }

}

